def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def put(n,v):
    with (OUT/n).open('x',encoding='utf-8',newline='\n') as f:f.write(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def ref(p,a=None,b=None):
    p=Path(p);r={'path':p.relative_to(ROOT).as_posix(),'sha256':sha(p),'bytes':p.stat().st_size}
    if a is not None:r['locator']={'line_start':a,'line_end':b or a}
    return r
def src(f,a=None,b=None):return ref(INP/'snapshot/current'/f,a,b)
def doc(f,a=None,b=None):return ref(INP/f,a,b)

